contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: fromBalanceHolder is an address whose balance we'll try to transfer from (must be != address(0)),
    // to is the recipient, and amount is the transfer amount to attempt.
    function run(address fromBalanceHolder, address to, uint256 amount) public payable {
        require(fromBalanceHolder != address(0) && to != address(0));

        // Observe totalSupply and balances before the transfer attempt.
        uint256 totalBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balFromBefore = c.balanceOf(fromBalanceHolder); if (__ESBMC_reverted()) return;
        uint256 balToBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;

        // Attempt transfer: since calls originate from this contract, we need to simulate that 'fromBalanceHolder' is msg.sender.
        // The contract C's transfer uses msg.sender, so to exercise transfer from 'fromBalanceHolder' we must rely on the fact
        // that initially owner may be this contract or not. We therefore instead call c._transfer via public transfer only from this contract.
        // To test transfer semantics in general we will call c.transfer(to, amount) from THIS contract and observe effects.
        // Record whether the call reverted.
        bool reverted;
        bool ok = c.transfer(to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe totals after the attempted transfer.
        uint256 totalAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balFromAfter = c.balanceOf(fromBalanceHolder); if (__ESBMC_reverted()) return;
        uint256 balToAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;

        // General rule asserted below:
        // 1) If the transfer succeeded (did not revert), then totalSupply is unchanged and the sum of the two observed balances changed by exactly zero
        //    apart from movement between them: (balFromBefore - balFromAfter) == (balToAfter - balToBefore) == amount OR transfer may have been from a different sender,
        //    so we conservatively assert that totalSupply unchanged and net sum of all observed balances (balFrom + balTo) changes by zero and equals totalSupply difference.
        // 2) If the 'to' address is the zero address, transfer must revert (this is a rule of C._transfer).

        // We express this as a single boolean formula below.
        bool toIsZero = (to == address(0));

        // change in observed pair-sum
        // using no underflow in assert: compare via additions
        uint256 sumBefore = balFromBefore + balToBefore;
        uint256 sumAfter = balFromAfter + balToAfter;

        assert(
            // transfers to zero address must revert
            (toIsZero ? reverted : true)
            &&
            // if not reverted, totalSupply unchanged and observed pair-sum unchanged
            (reverted || (totalAfter == totalBefore && sumAfter == sumBefore))
        );
    }

    receive() external payable {}
}

