pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address fromBalanceHolder, address to, uint256 amount) internal {
        vm.assume(fromBalanceHolder != address(0) && to != address(0));
        uint256 totalBefore;
        try c.totalSupply() returns (uint256 __r) { totalBefore = __r; } catch { return; }
        uint256 balFromBefore;
        try c.balanceOf(fromBalanceHolder) returns (uint256 __r) { balFromBefore = __r; } catch { return; }
        uint256 balToBefore;
        try c.balanceOf(to) returns (uint256 __r) { balToBefore = __r; } catch { return; }
        bool reverted;
        try c.transfer(to, amount) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 totalAfter;
        try c.totalSupply() returns (uint256 __r) { totalAfter = __r; } catch { return; }
        uint256 balFromAfter;
        try c.balanceOf(fromBalanceHolder) returns (uint256 __r) { balFromAfter = __r; } catch { return; }
        uint256 balToAfter;
        try c.balanceOf(to) returns (uint256 __r) { balToAfter = __r; } catch { return; }
        bool toIsZero = (to == address(0));
        uint256 sumBefore = balFromBefore + balToBefore;
        uint256 sumAfter = balFromAfter + balToAfter;
        assertTrue((toIsZero ? reverted : true)
            &&
            // if not reverted, totalSupply unchanged and observed pair-sum unchanged
            (reverted || (totalAfter == totalBefore && sumAfter == sumBefore)));
    }

    function testFuzz_run(address fromBalanceHolder, address to, uint256 amount) public {
        vm.assume(fromBalanceHolder.code.length == 0 && uint160(fromBalanceHolder) > 0xffff && fromBalanceHolder != address(this) && fromBalanceHolder != address(c) && fromBalanceHolder != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && fromBalanceHolder != 0x000000000000000000636F6e736F6c652e6c6f67 && fromBalanceHolder != 0x4e59b44847b379578588920cA78FbF26c0B4956C && fromBalanceHolder != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(fromBalanceHolder, to, amount);
    }

    receive() external payable {}
}
